class OcrJobStatusValues {
  const OcrJobStatusValues._();
  static const OcrJobStatus queued = "queued";
  static const OcrJobStatus processing = "processing";
  static const OcrJobStatus completed = "completed";
  static const OcrJobStatus failed = "failed";
  static const Set<OcrJobStatus> values = {queued, processing, completed, failed};
}

class GetHealthResponse {
  const GetHealthResponse({
    required this.status,
  });

  final String status;

  factory GetHealthResponse.fromJson(JsonObject json) {
    return GetHealthResponse(
      status: json["status"] as String,
    );
  }

  JsonObject toJson() {
    return {
      "status": status,
    };
  }
}

class GetHealthReadyResponse {
  const GetHealthReadyResponse({
    required this.status,
    required this.service,
    required this.checks,
  });

  final String status;
  final String service;
  final JsonObject checks;

  factory GetHealthReadyResponse.fromJson(JsonObject json) {
    return GetHealthReadyResponse(
      status: json["status"] as String,
      service: json["service"] as String,
      checks: JsonObject.from(json["checks"] as Map),
    );
  }

  JsonObject toJson() {
    return {
      "status": status,
      "service": service,
      "checks": checks,
    };
  }
}
